[SRSReportParameterAttribute(classStr(METArrivalDockCopyContract))]
class METArrivalDockCopyDP extends SRSReportDataProviderBase
{
    // Contains Agreement header data.
    METArrivalDockCopyHeader  METArrivalDockCopyHeader;
    
    // Contains Agreement lines data.
    METArrivalDockCopyLine    METArrivalDockCopyLine;
 
    
}

Method.Source:
[SRSReportDataSetAttribute(tablestr(METArrivalDockCopyHeader))]
public METArrivalDockCopyHeader getMETArrivalDockCopyHeader()
{
    select METArrivalDockCopyHeader;
    return METArrivalDockCopyHeader;
}

[SRSReportDataSetAttribute(tablestr(METArrivalDockCopyLine))]
public METArrivalDockCopyLine getMETArrivalDockCopyLine()
{
    select METArrivalDockCopyLine;
    return METArrivalDockCopyLine;
}

    /// <summary>
    /// Process report data.
    /// </summary>
    public void processReport()
    {
        METArrivalDockCopyContract contract;
        InventTransType            InventTransType;
        MetItemSiteSettingsSetup metItemSiteSettings;
        METInventItemOrderSetup  metInventItemOrderSetup;
        inventTable inventTable;
        METInventTable METInventTable;
        InventDim       InventDim;

 
        contract = this.parmDataContract() as METArrivalDockCopyContract;
        InventTransType = contract.parmInventTransType();
 
        // Get header record from the contract parameter
        if(InventTransType == InventTransType::Purch)
        {
            purchTable purchTable = purchTable::find(contract.parmInventTransRefId());
            METPurchTable METPurchTable = METPurchTable::find(purchTable.PurchId);

            METArrivalDockCopyHeader.PurchId = purchTable.PurchId;
           
            METArrivalDockCopyHeader.ShipName = purchTable.vendorName();
            METArrivalDockCopyHeader.ShipAddress = purchTable.vendorAddress();
            METArrivalDockCopyHeader.ShipPhone = purchTable.vendorPhone();
            METArrivalDockCopyHeader.ABNNumber = purchTable.vendTable_OrderAccount().VATNum;
            METArrivalDockCopyHeader.WarehouseName = InventLocation::find(purchTable.InventLocationId).Name;
            METArrivalDockCopyHeader.WarehouseAddress = InventLocation::find(purchTable.InventLocationId).address();
            METArrivalDockCopyHeader.WarehousePhone = this.getPODeliveryAddressContactPhone(purchTable.InventLocationId);
            METArrivalDockCopyHeader.PurchOrderDate = purchTable.DeliveryDate;
            METArrivalDockCopyHeader.DlvTerm    = DlvTerm::find(purchTable.DlvTerm).Txt;
            METArrivalDockCopyHeader.SpecialInstructions    =  purchTable.ReqAttention;

            // Task 90134: CB220 - Planner Codes - Check/Update Build
            // TODO Commenting for now, will have to be updated with buyer group logic
            /*
            if(metPurchTable.POPlannerCode)
            {
                METPlannerCodeSetup plannerCode;
                select firstonly plannerCode
                where   plannerCode.PlannerCode == metPurchTable.POPlannerCode;
                if(plannerCode)
                {
                    HcmWorker plannerWorker = HcmWorker::find(plannerCode.PlannerCodePersonnelNumber);
                    if(plannerWorker)
                    {
                        METArrivalDockCopyHeader.ContactName      = plannerWorker.name();
                        METArrivalDockCopyHeader.ContactEmail     = plannerWorker.email();
                        METArrivalDockCopyHeader.ContactPhone     = plannerWorker.phone();                    
                    }
                }
            }*/
            METArrivalDockCopyHeader.insert();

            purchLine purchLine;
            InventDim metInventDimSlotArea;
            
            while select purchLine where purchLine.PurchId == purchTable.PurchId && !purchLine.IsDeleted
                join InventDim where InventDim.inventDimId == purchLine.InventDimId
                join inventTable where inventTable.ItemId == purchLine.ItemId
                outer join METInventTable where METInventTable.ItemId == inventTable.ItemId
            {
                metItemSiteSettings.clear();

                select firstonly metItemSiteSettings
                where   metItemSiteSettings.ItemId          == purchLine.ItemId
                &&      metItemSiteSettings.InventSiteId    == purchTable.InventSiteId;

                metInventItemOrderSetup = METInventItemOrderSetup::findByItemAndSite(purchLine.ItemId, purchTable.InventSiteId);

                METArrivalDockCopyLine.clear();
               
                METArrivalDockCopyLine.Name                 = inventTable.productName(SystemParameters::getSystemLanguageId());
                METArrivalDockCopyLine.ItemId               = purchLine.ItemId;
                METArrivalDockCopyLine.LineNumber           = purchLine.LineNumber;
                METArrivalDockCopyLine.PurchUnitTxt         = purchLine.PurchUnit;
                METArrivalDockCopyLine.ItemSize             = METInventTable.ItemSize;

                metInventDimSlotArea.InventSiteId        = inventDim.InventSiteId;
                metInventDimSlotArea.InventLocationId    = inventDim.InventLocationId;

                metInventDimSlotArea = InventDim::findOrCreate(metInventDimSlotArea);

                METArrivalDockCopyLine.SlotArea = METReqItemTable::find(ReqItemTable::find(purchLine.ItemId, metInventDimSlotArea.inventDimId).RecId).SlotLoc1Area;

                METArrivalDockCopyLine.Qty                  = purchLine.PurchQty;
                METArrivalDockCopyLine.Ti                   = metInventItemOrderSetup.CartonPerLayer;
                METArrivalDockCopyLine.Hi                   = metInventItemOrderSetup.Layers;
                if(METArrivalDockCopyLine.Ti && METArrivalDockCopyLine.Hi)
                {
                    Qty metPalleyQty    = METArrivalDockCopyLine.Qty / METArrivalDockCopyLine.Ti / METArrivalDockCopyLine.Hi;

                    METArrivalDockCopyLine.PalletQty = roundup(metPalleyQty, 1);
                }

                METArrivalDockCopyLine.insert();
            }
        }
           
    }

    /// <summary>
    /// get the phone number for receiving dock
    /// </summary>
    /// <param name = "_metLogisticsLocationRole">LogisticsLocationRole</param>
    /// <returns>Phone</returns>
    public METWHPhone getPODeliveryAddressContactPhone(InventLocationId _InventLocationId)
    {     

        InventLocation                  	inventLocation;
        LogisticsEntityPostalAddressView    	postalAddressView;
        LogisticsElectronicAddress          	electronicAddress;
        LogisticsLocation                   	contactLocation;

        inventLocation = inventLocation::find(_InventLocationId);
        if (inventLocation)
        {
            select firstonly postalAddressView
            where   postalAddressView.Entity     == inventLocation.RecId
            &&      postalAddressView.EntityType == LogisticsLocationEntityType::Warehouse
            &&      postalAddressView.isPrimary  == NoYes::Yes;

            if (postalAddressView)
            {
                select firstOnly electronicAddress where electronicAddress.Type == LogisticsElectronicAddressMethodType::Phone
                join contactLocation where contactLocation.ParentLocation  == postalAddressView.Location
                    && contactLocation.RecId == electronicAddress.Location;

            }
        }
        return electronicAddress.Locator;

    }
